
'''
Solution for question 24 of Rosalind Bioinformatics stronghold
Title: A Simple Measure of Gene Order Similarity
Given: A positive integer n followed by a permutation π of length n
'''

'''
Expected Output:
A longest increasing subsequence of π
followed by a longest decreasing subsequence of π
'''

n=9959

π=list(map(int,input().split()))

# INCREASING SUBSEQUENCE

def inc_seq(inc):
  n=len(inc)

  lengths=[1]*n
  parents=[-1]*n

  for i in range(1,n):
    for j in range(i):
      if inc[j]<inc[i]:
        if lengths[j]+1>lengths[i]:
          lengths[i]=lengths[j]+1
          parents[i]=j


  max_ind=lengths.index(max(lengths))


  seq=[]
  current=max_ind
  while current!=-1:
    seq.append(inc[current])
    current=parents[current]

  return seq[::-1]



# DECREASING SUBSEQUENCE


def dec_seq(dec):
  n=len(dec)

  lengths=[1]*n
  parents=[-1]*n

  for i in range(1,n):
    for j in range(i):
      if dec[j]>dec[i]:
        if lengths[j]+1>lengths[i]:
          lengths[i]=lengths[j]+1
          parents[i]=j


  max_ind=lengths.index(max(lengths))


  seq=[]
  current=max_ind
  while current!=-1:
    seq.append(dec[current])
    current=parents[current]

  return seq[::-1]

print(*inc_seq(π))
print(*dec_seq(π))

